MOD = 10**9 + 7

def power(x, y, p):
    res = 1
    x = x % p
    while y > 0:
        if y & 1:
            res = (res * x) % p
        y = y >> 1
        x = (x * x) % p
    return res

def F(P):
    length = len(P)
    distinct = len(set(P))
    return power(length, distinct, MOD)

def main():
    T = int(input())
    results = []
    for _ in range(T):
        S = input().strip()
        result = 0
        for i in range(len(S)):
            distinct_chars = set()
            for j in range(i, len(S)):
                distinct_chars.add(S[j])
                result = (result + F(S[i:j+1])) % MOD
        results.append(result)
    for res in results:
        print(res)

if __name__ == "__main__":
    main()
